// This file is generated by AI.

// 拖放两条链路的纯逻辑:
//
// 1. **拖进编辑器的那段文本** = 「复制相对路径」的结果 (`browserRelativePath`)。三个入口
//    (右键菜单 / 剪贴板 / 拖拽) 必须给出同一个字符串, 否则"拖进去的"和"粘进来的"对不上 ——
//    这类不一致不会报错, 只会让用户写出找不到资源的脚本。
// 2. **拖拽阈值**: 没越过阈值必须仍然算单击 (文件行要打开、选项卡要激活)。
// 3. **系统拖放的坐标换算**: Tauri 给的是物理像素, 不除 `devicePixelRatio` 时 125% / 150%
//    缩放下落点会整体偏移 (而且看起来像"偶尔不灵")。

import { describe, expect, it } from 'vitest';

import { toClientPoint } from '../src/dnd/external-drop.svelte';
import { PATH_DRAG_THRESHOLD, pathDragReachedThreshold } from '../src/dnd/path-drag.svelte';
import { browserRelativePath, projectRelativePath } from '../src/lib/paths';

const PROJECT = 'C:\\Projects\\demo';

describe('browserRelativePath', () => {
  it('场景去掉 game/scene 前缀', () => {
    expect(browserRelativePath(PROJECT, `${PROJECT}\\game\\scene\\start.txt`)).toBe('start.txt');
    expect(browserRelativePath(PROJECT, `${PROJECT}\\game\\scene\\chapter1\\1-1.txt`)).toBe('chapter1/1-1.txt');
  });

  it('资源去掉 game/ 与可省略的第一级目录', () => {
    expect(browserRelativePath(PROJECT, `${PROJECT}\\game\\figure\\sakura.png`)).toBe('sakura.png');
    expect(browserRelativePath(PROJECT, `${PROJECT}\\game\\bgm\\main.mp3`)).toBe('main.mp3');
    // 图片的子目录是"可用的差别" (同一张图的不同表情), 不能一起剥掉
    expect(browserRelativePath(PROJECT, `${PROJECT}\\game\\figure\\sakura\\smile.png`)).toBe('sakura/smile.png');
  });

  it('配置卡与 game/ 下的普通文本保留原名', () => {
    expect(browserRelativePath(PROJECT, `${PROJECT}\\game\\config.txt`)).toBe('config.txt');
  });

  it('项目外的绝对路径原样返回 (拖进来也不会编出一个假相对路径)', () => {
    expect(browserRelativePath(PROJECT, 'D:\\elsewhere\\a.png')).toBe('D:/elsewhere/a.png');
  });

  it('大小写不敏感 (Windows 路径)', () => {
    expect(browserRelativePath(PROJECT, 'c:/projects/DEMO/game/scene/Start.txt')).toBe('Start.txt');
  });
});

describe('projectRelativePath', () => {
  it('项目根自己返回 "."', () => {
    expect(projectRelativePath(PROJECT, PROJECT)).toBe('.');
  });

  it('结尾分隔符与反斜杠都不影响结果', () => {
    expect(projectRelativePath(PROJECT, `${PROJECT}/game/scene/a.txt`)).toBe('game/scene/a.txt');
    expect(projectRelativePath(`${PROJECT}\\`, `${PROJECT}\\game\\scene\\a.txt`)).toBe('game/scene/a.txt');
  });
});

describe('pathDragReachedThreshold', () => {
  const origin = { x: 100, y: 100 };

  it('阈值内的位移仍然算单击', () => {
    expect(pathDragReachedThreshold(origin, { x: 100 + PATH_DRAG_THRESHOLD - 1, y: 100 })).toBe(false);
    expect(pathDragReachedThreshold(origin, { x: 100, y: 100 - (PATH_DRAG_THRESHOLD - 1) })).toBe(false);
  });

  it('任一轴达到阈值就算拖拽', () => {
    expect(pathDragReachedThreshold(origin, { x: 100 + PATH_DRAG_THRESHOLD, y: 100 })).toBe(true);
    expect(pathDragReachedThreshold(origin, { x: 100, y: 100 - PATH_DRAG_THRESHOLD })).toBe(true);
  });

  it('反向位移同样算 (向上 / 向左拖)', () => {
    expect(pathDragReachedThreshold(origin, { x: 100 - PATH_DRAG_THRESHOLD, y: 100 })).toBe(true);
  });
});

describe('toClientPoint', () => {
  it('100% 缩放时原样使用', () => {
    expect(toClientPoint({ x: 320, y: 180 }, 1)).toEqual({ x: 320, y: 180 });
  });

  it('高 DPI 下把物理像素换算成 CSS 像素', () => {
    expect(toClientPoint({ x: 400, y: 250 }, 1.25)).toEqual({ x: 320, y: 200 });
    expect(toClientPoint({ x: 400, y: 250 }, 2)).toEqual({ x: 200, y: 125 });
  });

  it('取不到缩放比例时按 1 处理 (偏一点也好过整条链路抛异常)', () => {
    expect(toClientPoint({ x: 10, y: 20 }, 0)).toEqual({ x: 10, y: 20 });
    expect(toClientPoint({ x: 10, y: 20 }, Number.NaN)).toEqual({ x: 10, y: 20 });
  });
});
